    "gift_email_how": "ਇਸ ਨੂੰ ਵਰਤਣ ਲਈ, ਆਮ ਵਾਂਗ ਇੱਕ ਅਪੌਇੰਟਮੈਂਟ ਬੁੱਕ ਕਰੋ ਅਤੇ ਇਹ ਕੋਡ {shop} ਨੂੰ ਦਿਓ — ਮੁੱਲ ਤੁਹਾਡੇ ਬਿੱਲ ਵਿੱਚੋਂ ਘਟ ਜਾਂਦਾ ਹੈ। ਬਾਕੀ ਕੋਈ ਵੀ ਬੈਲੰਸ ਅਗਲੀ ਵਾਰ ਲਈ ਕਾਰਡ 'ਤੇ ਰਹਿੰਦਾ ਹੈ।",
