    "feat1_t": "ਕਦੇ ਵੀ ਬੁੱਕ ਕਰੋ",
    "feat1_d": "ਗਾਹਕ ਇੱਕ ਸੇਵਾ, ਇੱਕ ਥੈਰੇਪਿਸਟ ਅਤੇ ਇੱਕ ਸਮਾਂ ਚੁਣਦੇ ਹਨ। ਤੁਸੀਂ ਭਰੇ ਹੋਏ ਕੈਲੰਡਰ ਨਾਲ ਜਾਗਦੇ ਹੋ — ਕੋਈ ਫ਼ੋਨ ਦੀ ਖਿੱਚੋਤਾਣ ਨਹੀਂ।",
    "feat2_t": "ਡਿਪਾਜ਼ਿਟ ਨੋ-ਸ਼ੋ ਰੋਕਦੇ ਹਨ",
