    "feat4_d": "ਆਪਣੀ ਪੂਰੀ ਟੀਮ ਸ਼ਾਮਲ ਕਰੋ, ਹਰ ਵਿਅਕਤੀ ਦੇ ਘੰਟੇ ਸੈੱਟ ਕਰੋ, ਅਤੇ ਗਾਹਕਾਂ ਨੂੰ “ਕੋਈ ਵੀ ਉਪਲਬਧ” ਚੁਣਨ ਦਿਓ।",
    "feat5_t": "ਆਪਣੇ ਖੁਦ ਦੇ ਘੰਟੇ ਸੈੱਟ ਕਰੋ",
    "feat5_d": "ਪ੍ਰਤੀ-ਥੈਰੇਪਿਸਟ ਹਫ਼ਤਾਵਾਰੀ ਸਮਾਂ-ਸਾਰਣੀ। Alisa ਸਿਰਫ਼ ਉਹੀ ਸਮੇਂ ਦੀ ਪੇਸ਼ਕਸ਼ ਕਰਦਾ ਹੈ ਜਦੋਂ ਤੁਸੀਂ ਅਸਲ ਵਿੱਚ ਖੁੱਲ੍ਹੇ ਹੋ।",
    "feat6_t": "ਇੱਕ ਸਾਂਝਾ ਕਰਨ ਯੋਗ ਪੇਜ",
